import {scannerDeviceToken} from './push.js?v=0.18.0';
import {cloudScanToken} from './cloud-scan.js?v=0.18.0';
export const OIL_INTERVAL=5000,OIL_WARNING=500;
export function oilRecord(last,due,at=new Date().toISOString()){last=Number(last);due=Number(due);if(!Number.isFinite(last)||last<0||!Number.isFinite(due)||due<=last)throw Error('Enter valid mileage; next oil change must be after the last one.');return {cycle:crypto.randomUUID(),lastChangedMileage:last,dueMileage:due,intervalMiles:OIL_INTERVAL,changedAt:at,emailEnabled:false};}
export function oilMileage(state){const oil=state.settings.oil;if(!oil)return null;const readings=[];for(const s of state.shifts){if(Number.isFinite(s.startOdometer))readings.push({at:s.startedAt,value:s.startOdometer});if(Number.isFinite(s.endOdometer)&&s.endedAt)readings.push({at:s.endedAt,value:s.endOdometer});}if(oil.manualReading)readings.push({at:oil.manualReading.at,value:oil.manualReading.mileage});readings.sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));return Math.max(oil.lastChangedMileage,readings[0]?.value??oil.lastChangedMileage);}
export function oilStatus(oil,mileage){const remaining=oil.dueMileage-mileage;return {remaining,warningAt:oil.dueMileage-OIL_WARNING,stage:remaining<=0?'due':remaining<=OIL_WARNING?'soon':'ok'};}
export function updateOilSchedule(state,last,due){const previous=state.settings.oil;if(previous&&previous.lastChangedMileage===Number(last)&&previous.dueMileage===Number(due))return previous;const next=oilRecord(last,due);next.emailEnabled=!!previous?.emailEnabled;if(previous?.manualReading)next.manualReading=previous.manualReading;state.settings.oil=next;return next;}
export function recordOilChange(state,mileage,at=new Date().toISOString()){const previous=state.settings.oil;if(!previous)throw Error('Set up oil-change reminders first.');mileage=Number(mileage);if(!Number.isFinite(mileage)||mileage<previous.lastChangedMileage)throw Error('Enter the odometer mileage when the oil was changed.');const next=oilRecord(mileage,mileage+OIL_INTERVAL,at);next.emailEnabled=!!previous.emailEnabled;next.manualReading={mileage:Math.max(oilMileage(state),mileage),at};state.settings.oil=next;return next;}
export function recordOilMileage(state,mileage,at=new Date().toISOString()){mileage=Number(mileage);if(!Number.isFinite(mileage)||mileage<state.settings.oil.lastChangedMileage)throw Error('Current mileage cannot be below the last oil-change mileage.');state.settings.oil.manualReading={mileage,at};}
const API='https://delivery-manager-reminders.tonykevinjr.workers.dev',QUEUE='delivery-manager-oil-email-pending-v1',REVISION='delivery-manager-oil-email-revision-v1';let pending=Promise.resolve(),lastSignature='',service={configured:false,checked:false,error:''};
const token=()=>cloudScanToken()||scannerDeviceToken();
async function request(path,data={}){const credential=token();if(!credential)throw Error('Connect the ticket scanner or lock-screen reminders first to identify this installation.');if(!navigator.onLine)throw Error('Connect to the internet to update email reminders.');const r=await fetch(API+path,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+credential},body:JSON.stringify(data),cache:'no-store',keepalive:true,signal:AbortSignal.timeout(15000)});const result=await r.json();if(!r.ok)throw Error(result.error||'Could not update oil reminders.');return result;}
export const oilEmailStatus=()=>({...service,connected:!!token()});
export async function checkOilEmail(){try{service={...await request('/oil/status'),checked:true,error:''};return service;}catch(e){service={...service,checked:true,error:e.message};throw e;}}
export function syncOilEmail(state,{force=false,demo=false}={}){if(demo||!state.settings.oil)return Promise.resolve();const oil=state.settings.oil,revision=Math.max(Date.now(),Number(localStorage.getItem(REVISION)||0)+1);localStorage.setItem(REVISION,String(revision));let payload={enabled:!!oil.emailEnabled,cycle:oil.cycle,lastChangedMileage:oil.lastChangedMileage,dueMileage:oil.dueMileage,intervalMiles:OIL_INTERVAL,mileage:oilMileage(state),revision};let queued;try{queued=JSON.parse(localStorage.getItem(QUEUE)||'null');}catch{}if(!oil.emailEnabled&&!force&&queued?.enabled===false)payload=queued;const signature=JSON.stringify({...payload,revision:0});if(!force&&(!oil.emailEnabled&&!queued||signature===lastSignature&&!queued))return pending;localStorage.setItem(QUEUE,JSON.stringify(payload));pending=pending.catch(()=>{}).then(async()=>{try{const value=await request('/oil/sync',payload);service={...service,...value,checked:true,error:''};lastSignature=signature;try{if(JSON.parse(localStorage.getItem(QUEUE)||'null')?.revision===payload.revision)localStorage.removeItem(QUEUE);}catch{}}catch(e){service={...service,error:e.message};throw e;}});return pending;}
